// mwg-train-64b. `check:route-conformance` read `pilot/training-projects` - generated by
// `npm run scaffold:train-corpus` and deliberately not committed - with no absent-input handling at all, so on a
// clean checkout it died on the first `spec.json` with an unhandled ENOENT and exit 1. That made it red for a
// reason that is not a defect, and it took `test/checks-wired` down with it, because that test EXECUTES this
// check. These tests drive the real CLI through a fixture shaped like a clean checkout: script, corpus and
// manifest present, generated projects absent. None of them scaffolds anything, so the file is cheap.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import test from 'node:test';

const ROOT = resolve(import.meta.dirname, '..');
const SCRIPT = join(ROOT, 'scripts', 'check-route-conformance.mjs');

// A tree with the committed inputs but NO generated projects. The script is COPIED, not symlinked: it resolves
// its repo root from its own file location, so a symlink would make it read the real checkout instead of this
// fixture and the fixture would then prove nothing about a clean checkout.
function bareTree() {
  const dir = mkdtempSync(join(tmpdir(), 'rc-bare-'));
  mkdirSync(join(dir, 'scripts'), { recursive: true });
  mkdirSync(join(dir, 'pilot'), { recursive: true });
  mkdirSync(join(dir, 'docs', 'train', 'briefs'), { recursive: true });
  copyFileSync(SCRIPT, join(dir, 'scripts', 'check-route-conformance.mjs'));
  symlinkSync(join(ROOT, 'pilot', 'TRAINING_CORPUS.json'), join(dir, 'pilot', 'TRAINING_CORPUS.json'));
  symlinkSync(join(ROOT, 'pilot', 'training-archetypes.mjs'), join(dir, 'pilot', 'training-archetypes.mjs'));
  symlinkSync(join(ROOT, 'docs', 'train', 'briefs', 'manifest.jsonl'), join(dir, 'docs', 'train', 'briefs', 'manifest.jsonl'));
  return dir;
}

function runCli(cwd, args = []) {
  try {
    const stdout = execFileSync(process.execPath, [join(cwd, 'scripts', 'check-route-conformance.mjs'), ...args], {
      cwd,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: 120000,
    });
    return { code: 0, stdout, stderr: '' };
  } catch (err) {
    return { code: err.status ?? -1, stdout: err.stdout ?? '', stderr: err.stderr ?? '' };
  }
}

test('end to end: a clean checkout SKIPS with a label, and does not crash', () => {
  const dir = bareTree();
  try {
    const result = runCli(dir);
    assert.equal(result.code, 0, `expected the skip to exit 0, got ${result.code}: ${result.stdout}${result.stderr}`);
    const out = result.stdout + result.stderr;
    assert.match(out, /SKIPPED/, 'the run must say it skipped');
    // The defect itself: this used to be an unhandled ENOENT stack trace and exit 1.
    assert.doesNotMatch(out, /ENOENT/, 'a clean checkout must not crash on a generated input it never had');
    assert.doesNotMatch(out, /at Object\.<anonymous>/, 'no stack trace: the skip is a verdict, not a crash');
    assert.match(out, /npm run scaffold:train-corpus/, 'a skip must name the command that produces the input');
    assert.match(out, /NOT a conformance result/, 'a skip must not be mistakable for a result');
    // A skip is not a pass. Reporting "PASS" over zero compared projects is the failure mode mwg-train-xku named
    // for the sibling check, and it must not come back here.
    assert.doesNotMatch(out, /PASS -/, 'a skipped run must not report a conformance pass');
    assert.doesNotMatch(out, /declare every route/, 'a skipped run must not claim any project was checked');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a projects path the caller NAMED is fatal when absent, so a typo cannot look clean', () => {
  const dir = bareTree();
  try {
    const result = runCli(dir, ['--projects', '/definitely-not-a-projects-dir']);
    assert.equal(result.code, 1, `expected a named absent path to exit 1, got ${result.code}: ${result.stdout}${result.stderr}`);
    const out = result.stdout + result.stderr;
    assert.match(out, /FATAL/);
    assert.match(out, /does not exist/);
    assert.doesNotMatch(out, /SKIPPED/, 'a path the caller named must not be read as absent-by-design');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a corpus defect fails even while the generated projects are absent', () => {
  // Ordering property, and the reason the projects verdict is applied AFTER the corpus is validated: a corpus
  // the caller named is a committed input whose defects must fail. Applying the skip first would hide a broken
  // corpus behind a missing generated directory and turn it into a clean exit 0.
  const dir = bareTree();
  const empty = join(dir, 'empty-corpus.json');
  writeFileSync(empty, '{"projects": []}');
  try {
    const result = runCli(dir, ['--corpus', empty]);
    assert.equal(result.code, 1, `expected an empty corpus to exit 1, got ${result.code}: ${result.stdout}${result.stderr}`);
    assert.match(result.stdout + result.stderr, /FAIL - no projects found in corpus/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('the CLI still RUNS when invoked through a symlink, and the skip is machine-readable under --json', () => {
  const dir = bareTree();
  try {
    // A guard that concludes "this was an import" exits 0 having done nothing, which for a check is
    // indistinguishable from passing. This check has no such guard; this pins that it stays that way.
    const link = join(dir, 'linked-check.mjs');
    symlinkSync(join(dir, 'scripts', 'check-route-conformance.mjs'), link);
    const viaLink = execFileSync(process.execPath, [link], {
      cwd: dir,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: 120000,
    });
    assert.match(viaLink, /SKIPPED/, 'the CLI must still run when reached through a symlink');

    const json = runCli(dir, ['--json']);
    assert.equal(json.code, 0);
    const parsed = JSON.parse(json.stdout);
    assert.equal(parsed.skipped, true, 'a --json consumer must be able to see the skip');
    assert.equal(parsed.reason, 'projects-missing');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
